CREATE PROCEDURE CLAIMS.NESTED_CONDITION_TEST (
    IN P_CLAIM_ID BIGINT,
    OUT P_RESULT VARCHAR(20)
)
LANGUAGE SQL
BEGIN
    SET P_RESULT = 'START';
    INNER_BLOCK: BEGIN
        DECLARE CUSTOMER_NOT_FOUND CONDITION FOR SQLSTATE '02000';
        DECLARE EXIT HANDLER FOR CUSTOMER_NOT_FOUND
        BEGIN
            SET P_RESULT = 'NOT_FOUND';
        END;

        SELECT STATUS
          INTO P_RESULT
          FROM CLAIM
         WHERE CLAIM_ID = P_CLAIM_ID;
    END INNER_BLOCK;
END
